WITH with_windows AS (SELECT id, dept_name, location, MIN(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_budget, AVG(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_budget, MAX(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_budget, SUM(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_budget, ROUND(budget / SUM(budget) OVER (PARTITION BY location), 4) AS budget_share FROM departments WHERE budget BETWEEN 1234000 AND 2704000) SELECT dept_name, COUNT(*) FILTER (WHERE location = 'Bangkok') AS bangkok_rows, ROUND(AVG(last7_sum_budget), 2) AS avg_last7_sum_budget, ROUND(SUM(budget_share) / NULLIF(COUNT(CASE WHEN location = 'London' THEN 1 END), 0), 2) AS budget_share_per_london, COUNT(*) AS cnt FROM with_windows GROUP BY dept_name ORDER BY avg_last7_sum_budget DESC;
